//==============================================================================
// Module: counter_16bit
// Description: 16-bit Synchronous Up/Down Counter with Enable & Terminal Count
// Auto-generated by Spec2RTL Autonomous Engine
//==============================================================================
module counter_16bit (
    input  wire             clk,
    input  wire             rst,
    input  wire             enable,
    input  wire             up_down, // 1: Count Up, 0: Count Down
    output reg  [15:0] count,
    output wire             tc       // Terminal Count flag
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 16'd0;
        end else if (enable) begin
            if (up_down)
                count <= count + 1'b1;
            else
                count <= count - 1'b1;
        end
    end

    assign tc = (up_down && count == {16{1'b1}}) || (!up_down && count == 16'd0);

endmodule
